options.getOption:
// Every sound hour by hour: the share of the recordings in the hour in which most volunteers
// heard it, under every filter, in the map's bands and colours, so this chart is also the map's
// legend. Click a sound (a cell of its row, or its name) to put it on the map and the months: its
// row is outlined. A click never clears the pick, so there is always a sound on the map.
// @constants begin
const VAR = 'mapSound';
const PICKED = context.grafana.replaceVariables('${mapSound}');
const BREAKS = [2, 5, 10, 20, 35];
const COLORS = ['#4C0035', '#880030', '#B72F15', '#D6610A', '#EF9100', '#FFC300'];
const UNIT = '%';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const soundCol = col('sound');
const ordCol = col('ord').map(Number);
const hourCol = col('hour').map(Number);
const shareCol = col('share').map((v) => (v == null ? null : Number(v)));
const nCol = col('n').map(Number);

// The sounds in SONYC's order, top to bottom (the axis is inverted).
const order = new Map();
soundCol.forEach((s, i) => order.set(s, ordCol[i]));
const sounds = Array.from(order.keys()).sort((a, b) => order.get(a) - order.get(b));
const row = new Map(sounds.map((s, i) => [s, i]));
const hours = Array.from({ length: 24 }, (_, h) => String(h));

const cells = soundCol.map((s, i) => ({
  value: [hourCol[i], row.get(s), shareCol[i]],
  n: nCol[i],
  itemStyle: s === PICKED ? { borderColor: text, borderWidth: 1.5 } : { borderColor: 'transparent', borderWidth: 0 },
}));

const pick = (sound) => {
  if (sound && sound !== context.grafana.replaceVariables('${' + VAR + '}')) {
    location.partial({ ['var-' + VAR]: sound }, true);
  }
};
chart.off('click');
chart.on('click', (event) => {
  if (event.componentType === 'yAxis') {
    pick(event.value);
  } else if (Array.isArray(event.value)) {
    pick(sounds[event.value[1]]);
  }
});

const fmt = (v) => (v < 10 ? v.toFixed(1) : v.toFixed(0));
const pieces = COLORS.map((color, k) => {
  const lo = k === 0 ? null : BREAKS[k - 1];
  const hi = k === BREAKS.length ? null : BREAKS[k];
  const label = lo == null ? `under ${hi} ${UNIT}` : hi == null ? `${lo} ${UNIT} or more` : `${lo}–${hi} ${UNIT}`;
  return { ...(lo == null ? {} : { gte: lo }), ...(hi == null ? {} : { lt: hi }), color, label };
});

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 16, top: 34, bottom: 30, containLabel: true },
  tooltip: {
    formatter: (p) => {
      const [h, r, v] = p.value;
      const n = p.data.n;
      return `<b>${sounds[r]}</b>, ${h}:00 to ${h + 1}:00<br/>${v == null ? 'no recordings' : `${fmt(v)} ${UNIT} of ${n.toLocaleString('en-US')} recordings`}`;
    },
  },
  visualMap: {
    type: 'piecewise',
    dimension: 2,
    pieces,
    orient: 'horizontal',
    left: 'center',
    top: 0,
    itemWidth: 14,
    itemHeight: 10,
    itemGap: 12,
    selectedMode: false,
    textStyle: { color: muted, fontSize: 11 },
  },
  xAxis: {
    type: 'category',
    data: hours,
    name: 'hour of day (New York) →',
    nameLocation: 'middle',
    nameGap: 22,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted, fontSize: 10 },
    axisTick: { show: false },
    axisLine: { show: false },
    splitArea: { show: false },
  },
  yAxis: {
    type: 'category',
    data: sounds,
    inverse: true,
    triggerEvent: true,
    axisTick: { show: false },
    axisLine: { show: false },
    axisLabel: {
      fontSize: 11,
      color: muted,
      formatter: (value) => (value === PICKED ? `{picked|▸ ${value}}` : value),
      rich: { picked: { color: text, fontWeight: 'bold', fontSize: 11 } },
    },
  },
  series: [
    {
      type: 'heatmap',
      data: cells,
      cursor: 'pointer',
      itemStyle: { borderColor: 'transparent' },
      emphasis: { itemStyle: { borderColor: text, borderWidth: 1 } },
    },
  ],
};

visualEditor.code:
return {
  dataset: context.editor.dataset,
  series: context.editor.series,
  xAxis: {
    type: 'time',
  },
  yAxis: {
    type: 'value',
    min: 'dataMin',
  },
}
